def ricerca(lista, x):
    inizio, fine = 0, len(lista) - 1
    while inizio < fine:
        medio = (inizio + fine) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            inizio = medio + 1
        else:
            fine = medio - 1
    return None

def ricerca(lista, x):
    if len(lista) == 0:
        return None
    medio = len(lista) // 2
    if lista[medio] == x:
        return medio
    if lista[medio] < x:
        return ricerca(lista[medio + 1:], x)
    return ricerca(lista[:medio], x)

def ricerca(lista, x, i, f):
    if i > f:
        return None
    medio = (i + f) // 2
    if lista[medio] == x:
        return medio
    if lista[medio] < x:
        return ricerca(lista, x, medio + 1, f)
    return ricerca(lista, x, i, medio - 1)

