def duplicati(A, M):
    visto = [False] * (M + 1)
    for v in A:
        if visto[v]:
            return True
        visto[v] = True
    return False

def duplicati(A):
    for i in range(len(A)):
        if A[i] in A[i + 1:]:
            return True
    return False

def duplicati_ordinato(A):
    for i in range(len(A) - 1):
        if A[i] == A[i + 1]:
            return True
    return False

def coppia(A, x):
    i, j = 0, len(A) - 1
    while i < j:
        s = A[i] + A[j]
        if s == x:
            return True
        if s < x:
            i = i + 1
        else:
            j = j - 1
    return False
